import React, { useEffect, useState } from 'react';
import { Box, Text, Select, VStack, HStack, IconButton } from '@chakra-ui/react';
import { ChevronLeftIcon, ChevronRightIcon } from "@chakra-ui/icons";
import { Expense } from '../../types/expenses';
import { currentMonth, currentWeek, currentYear, months } from '../../utils/constant';
import { getWeeksInMonth, getWeekRange, getWeekDates, fetchExpenses } from '../../utils/filterUtils';

export const ExpensesSummary: React.FC = () => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [filteredExpenses, setFilteredExpenses] = useState<Expense[]>([]);
  const [year, setYear] = useState<number>(currentYear);
  const [month, setMonth] = useState<number>(currentMonth);
  const [week, setWeek] = useState<string>(currentWeek);
  const [weeks, setWeeks] = useState<string[]>([]);
  const [day, setDay] = useState<string>('All');
  const [days, setDays] = useState<string[]>([]);

  const itemsPerPage = 20;
  const [currentPage, setCurrentPage] = useState(1);

  useEffect( () => {
    const fetchData = async () => {
      const data = await fetchExpenses()
      if(data) setExpenses(data)
    } 
    fetchData()
  }, []);

  useEffect(() => {
    setWeeks(getWeeksInMonth(year, month));
  }, [year, month]);

  useEffect(() => {
    if (week !== 'All') {
      const weekNum = parseInt(week.replace('Week ', ''));
      const weekDates = getWeekDates(year, month, weekNum);
      const formattedDays = weekDates.map(date =>
        `${date.getDate()} ${months[date.getMonth()].substring(0, 3)}`
      );
      setDays(['All', ...formattedDays]);
    } else {
      setDays([]);
      setDay('All');
    }
  }, [week, year, month]);

  useEffect(() => {
    const filtered = expenses.filter(exp => {
      const date = exp.date.toDate();
      const isInMonthYear = date.getFullYear() === year && date.getMonth() === month;
      if (!isInMonthYear) return false;

      if (week !== 'All') {
        const expWeek = getWeekRange(date);
        if (week !== `Week ${expWeek}`) return false;

        if (day !== 'All') {
          const selectedDay = parseInt(day.split(' ')[0]);
          return date.getDate() === selectedDay;
        }
      }

      return true;
    });

    setFilteredExpenses(filtered);
    setCurrentPage(1);
  }, [expenses, year, month, week, day]);

  const handleYearChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const newYear = parseInt(e.target.value);
    setYear(newYear);
    setMonth(currentMonth);
    setWeek('All');
    setDay('All');
  };

  const handleMonthChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const newMonth = parseInt(e.target.value);
    setMonth(newMonth);
    setWeek('All');
    setDay('All');
  };

  const totalAmount = filteredExpenses.reduce((sum, exp) => sum + exp.amount, 0);
  const totalPages = Math.ceil(filteredExpenses.length / itemsPerPage);
  const paginatedExpenses = filteredExpenses.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  return (
    <Box p={4}>
      <Box display="flex" gap={4} mb={6} flexWrap="wrap">
        <Select value={year} onChange={handleYearChange} width="150px">
          {[...Array(5)].map((_, i) => {
            const y = currentYear - i;
            return <option key={y} value={y}>{y}</option>;
          })}
        </Select>

        <Select value={month} onChange={handleMonthChange} width="150px">
          {months.map((m, index) => (
            <option key={index} value={index}>{m}</option>
          ))}
        </Select>

        <Select value={week} onChange={(e) => setWeek(e.target.value)} width="150px">
          {weeks.map((w, index) => (
            <option key={index} value={w}>{w}</option>
          ))}
        </Select>

        {/* Day Filter only when week is selected */}
        {week !== 'All' && (
          <Select value={day} onChange={(e) => setDay(e.target.value)} width="150px">
            {days.map((d, index) => (
              <option key={index} value={d}>{d}</option>
            ))}
          </Select>
        )}
      </Box>

      <Text fontWeight="bold">Total: ₹{totalAmount}</Text>

      <VStack mt={4} spacing={4} align="stretch">
        {paginatedExpenses.length > 0 ? (
          paginatedExpenses.map(exp => (
            <Box key={exp.id} p={4} shadow="md" borderWidth="1px" borderRadius="md">
              <Text><strong>Amount:</strong> ₹{exp.amount}</Text>
              <Text><strong>Date:</strong> {exp.date.toDate().toDateString()}</Text>
              <Text><strong>Category:</strong> {exp.category}</Text>
              <Text><strong>Description:</strong> {exp.description}</Text>
            </Box>
          ))
        ) : (
          <Box p={4} shadow="md" borderWidth="1px" borderRadius="md">
            <Text>No Record Found</Text>
          </Box>
        )}
      </VStack>

      {totalPages > 1 && (
        <HStack mt={4} justifyContent="center">
          <IconButton
            aria-label="Previous Page"
            icon={<ChevronLeftIcon />}
            onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))}
            isDisabled={currentPage === 1}
            variant="outline"
          />
          <Text>{currentPage} / {totalPages}</Text>
          <IconButton
            aria-label="Next Page"
            icon={<ChevronRightIcon />}
            onClick={() => setCurrentPage((prev) => Math.min(prev + 1, totalPages))}
            isDisabled={currentPage === totalPages}
            variant="outline"
          />
        </HStack>
      )}
    </Box>
  );
};
