import { Button, Heading, Input, VStack, Text, Flex } from '@chakra-ui/react';
import { createUserWithEmailAndPassword } from 'firebase/auth';
import React, { useState } from 'react'
import { auth, db } from '../Firebase';
import { useNavigate } from 'react-router-dom';
import { doc, setDoc } from 'firebase/firestore';

export const Signup:React.FC = () => {
    const [email, setEmail] = useState<string>("");
    const [password, setPassword] = useState<string>("");
    const [error, setError] = useState<string>("");
    const [username, setUsername] = useState("");
    const navigate = useNavigate();
  
    const handleSignup = async () => {
      try {
        const userCredential = await createUserWithEmailAndPassword(auth, email, password);
        const user = userCredential.user;
    
        // Add additional data to Firestore
        await setDoc(doc(db, "users", user.uid), {
          username: username,
          email: user.email,
        });
        navigate("/login")
      } catch (err:any) {
        setError(err.message);;
      }
    };
  
    return (
       <Flex minH={`${window.innerHeight-50}px`} justify="center" align="center" bg="gray.50">
          <Flex
            direction="column"
            justifyContent="center"
            alignItems="center"
            textAlign="center"
            p={10}
            maxW="md"
            boxShadow="md"
            borderRadius="md"
            bg="white"
          >
            <Heading mb={5}>Sign Up</Heading>
            {error && <Text color="red.500">{error}</Text>}
            <VStack spacing={4}>
              <Input
                placeholder="Username"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
              />
              <Input
                type="email"
                placeholder="Email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                focusBorderColor="blue.500"
              />
              <Input
                type="password"
                placeholder="Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                focusBorderColor="blue.500"
              />
              <Button colorScheme="blue" onClick={handleSignup} width="full">Sign Up</Button>
              <Text>
                Already have an account? <Button variant="link" onClick={() => navigate("/login")}>Login</Button>
              </Text>
            </VStack>
        </Flex>
      </Flex>
    );
}

export default Signup
