import React, { useEffect, useState } from "react";
import { collection, addDoc, Timestamp, query, where, getDocs } from "firebase/firestore";
import { Box, Input, Button, VStack, Heading, Alert, AlertIcon, AlertTitle, useToast, Select } from "@chakra-ui/react";
import { auth, db } from "../../auth";
import { useNavigate } from "react-router-dom";
import { Categories } from "../../types/expenses";

export const Spends:React.FC = () => {
    const [amount, setAmount] = useState("");
    const [description, setDescription] = useState("");
    const [message, setMessage] = useState("");
    const [categories, setCategories] = useState<Categories[]>([]);
    const [category, setCategory] = useState("")

    const getTodayDate = () => {
        const today = new Date();
        const yyyy = today.getFullYear();
        const mm = String(today.getMonth() + 1).padStart(2, "0");
        const dd = String(today.getDate()).padStart(2, "0");
        return `${yyyy}-${mm}-${dd}`;
    };

    const [date, setDate] = useState(getTodayDate());
    const navigate = useNavigate();
    const toast = useToast();

    useEffect(()=>{
        const fetchExpenses = async () => {
            const user = auth.currentUser;
            if (!user) return;
            const expensesRef = collection(db, 'categories');
            const q = query(expensesRef, where('userId', '==', user.uid));
            const snapshot = await getDocs(q);
            const data: Categories[] = snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
            })) as Categories[];
            setCategories(data);
            setCategory(data[0].category)
        };
    
        fetchExpenses();
    },[])

    const handleSubmit = async () => {
        if (!amount || !description || !date || !category) {
            setMessage("Please fill in all fields.");
            return;
        }

        try {
            const user = auth.currentUser;
            if (!user) {
            setMessage("You must be logged in to add data.");
            return;
            }

            await addDoc(collection(db, "expenses"), {
            userId: user.uid,
            amount: parseFloat(amount),
            description,
            category: category,
            date: Timestamp.fromDate(new Date(date)),
            createdAt: Timestamp.now(),
            });

            // Clear fields and show success toast
            setAmount("");
            setDescription("");
            setDate(getTodayDate());
            setMessage("");

            toast({
            position: "top",
            title: "Record Added Successfully!",
            status: "success",
            duration: 4000,
            isClosable: true,
            });

            navigate("/");
        } catch (error: any) {
            toast({
            position: "top",
            title: "Error saving data",
            description: error.message,
            status: "error",
            duration: 4000,
            isClosable: true,
            });

            navigate("/");
        }
    };
    return (
        <Box maxW="md" mx="auto" mt={8} p={5} boxShadow="md" borderRadius="md">
            <Heading size="md" mb={4}>Add Expense Record</Heading>
                {message && <Alert status='warning'>
                            <AlertIcon />
                            <AlertTitle>{message}</AlertTitle>
                            </Alert>}
            <VStack spacing={4}>
                <Input
                    placeholder="Amount"
                    value={amount}
                    onChange={(e) => setAmount(e.target.value)}
                    type="number"
                />
                <Input
                    placeholder="Description"
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                />
                <Select value={category} onChange={(e) => setCategory(e.target.value)}>
                    {categories.map((w, index) => (
                    <option key={index} value={w.category}>{w.category}</option>
                    ))}
                </Select>
                <Input
                    placeholder="Date"
                    value={date}
                    onChange={(e) => setDate(e.target.value)}
                    type="date"
                />
                <Button colorScheme="blue" onClick={handleSubmit} width="full">
                    Submit
                </Button>
            </VStack>
        </Box>
    )
}

export default Spends
