import { onAuthStateChanged, User } from 'firebase/auth';
import React, { useEffect, useState } from 'react'
import { auth, db } from '../auth';
import { doc, getDoc } from 'firebase/firestore';
import { Avatar, Box, Button, Flex, Menu, MenuButton, MenuItem, MenuList, Text } from '@chakra-ui/react';
import { ChevronDownIcon } from "@chakra-ui/icons";
import { useNavigate } from 'react-router-dom';
import { AuthService } from '../Services';

export const Users:React.FC = () => {
    const [username, setUsername] = useState<string | null>(null);
    const [user, setUser] = useState<User | null>(null);

    const navigate = useNavigate();

    const handleLogout = async () => {
      await AuthService.logout(auth);
      navigate("/login");
    };

    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, async (currentUser) => {
          if (currentUser) {
            setUser(currentUser);
      
            // Fetch username from Firestore
            const userDocRef = doc(db, "users", currentUser.uid);
            const userDocSnap = await getDoc(userDocRef);
      
            if (userDocSnap.exists()) {
              const userData = userDocSnap.data();
              setUsername(userData.username);
            } else {
              console.log("No such document!");
            }
          } else {
            setUser(null);
            setUsername(null);
          }
        });
      
        return () => unsubscribe();
      }, []);
  return (
    <Box>
      {user && username && (
        <Menu>
          <MenuButton as={Button} rightIcon={<ChevronDownIcon />} bg={"transparent"} _hover={{bg:"white"}} _active={{g:"white"}}>
            <Flex gap={2} alignItems={"center"}><Avatar size={"sm"} bg="gray.300" ml={2}/> <Text>{username}</Text></Flex>
          </MenuButton>
          <MenuList>
            <MenuItem onClick={handleLogout}>Logout</MenuItem>
          </MenuList>
        </Menu>
      )}
    </Box>
    
  )
}

export default Users
