import React, { useEffect, useState } from 'react';
import {
  Box,
  Card,
  CardBody,
  HStack,
  Select,
  SimpleGrid,
  Spinner,
  Text,
  VStack,
} from '@chakra-ui/react';
import { Expense } from '../../types/expenses';
import { fetchExpenses, getExpensesCategoryData, getWeeksInMonth } from '../../utils/filterUtils';
import { currentMonth, currentWeek, currentYear, months } from '../../utils/constant';

const CategorySummary:React.FC = () => {

    const [expenses, setExpenses] = useState<Expense[]>([]);
    const [loading, setLoading] = useState(true);
    const [year, setYear] = useState<number>(currentYear);
    const [month, setMonth] = useState<number>(currentMonth);
    const [week, setWeek] = useState<string>(currentWeek);
    const [weeks, setWeeks] = useState<string[]>([]);
    const [summary, setSummary] = useState<Record<string, number>>({});

    useEffect( () => {
        const fetchData = async () => {
            setLoading(true);
            const data = await fetchExpenses()
            if(data) setExpenses(data)
            setLoading(false);
        } 
        fetchData()
    }, []);

    useEffect(() => {
        setWeeks(getWeeksInMonth(year, month));
    }, [year, month]);

  useEffect(() => {
    const grouped = getExpensesCategoryData(expenses, year, month, week)
    setSummary(grouped);
  }, [expenses, year, month, week]);

    const handleYearChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      const newYear = parseInt(e.target.value);
      setYear(newYear);
      setMonth(currentMonth);
      setWeek('All');
    };
  
    const handleMonthChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      const newMonth = parseInt(e.target.value);
      setMonth(newMonth);
      setWeek('All');
    };

  return (
    <Box p={4}>
      <VStack align="start" spacing={4}>
        <HStack spacing={4} w="100%">
            <Select value={year} onChange={handleYearChange} width="150px">
                {[...Array(5)].map((_, i) => {
                    const y = currentYear - i;
                    return <option key={y} value={y}>{y}</option>;
                })}
            </Select>

          <Select value={month} onChange={handleMonthChange} width="150px">
                    {months.map((m, index) => (
                      <option key={index} value={index}>{m}</option>
                    ))}
                  </Select>
          
                  <Select value={week} onChange={(e) => setWeek(e.target.value)} width="150px">
                    {weeks.map((w, index) => (
                      <option key={index} value={w}>{w}</option>
                    ))}
                  </Select>
        </HStack>
      </VStack>

      <Box mt={6}>
        {loading ? (
          <Spinner size="xl" />
        ) : (
            Object.entries(summary).length > 0 ? <SimpleGrid columns={[1, 2, 3]} spacing={4}>
            {Object.entries(summary).map(([category, total]) => (
              <Card key={category} boxShadow="md" borderRadius="xl" p={4}>
                <CardBody>
                  <Text fontSize="xl" fontWeight="bold">{category}</Text>
                  <Text fontSize="lg">Total: ₹{total}</Text>
                </CardBody>
              </Card>
            ))}
          </SimpleGrid> :
          (
            <SimpleGrid columns={[1, 2, 3]} spacing={4}>
                <Card boxShadow="md" borderRadius="xl" p={4}>
                    <CardBody>
                    <Text fontSize="xl" fontWeight="bold">No Record Found</Text>
                    </CardBody>
                </Card>
            </SimpleGrid>
            )
        )}
      </Box>
    </Box>
  );
};

export default CategorySummary;
