import React, { useState } from 'react'
import { collection, addDoc, Timestamp } from "firebase/firestore";
import { Box, Input, Button, VStack, Heading, Alert, AlertIcon, AlertTitle, useToast } from "@chakra-ui/react";
import { auth, db } from "../../auth";
import { useNavigate } from "react-router-dom";

export const Categories:React.FC = () => {
    const [message, setMessage] = useState("");
    const [category, setCategory] = useState("")

    const navigate = useNavigate();
    const toast = useToast();

    const handleCategorySubmit  = async () =>{
        if (!category) {
            setMessage("Please fill in all fields.");
            return;
        }

        try {
            const user = auth.currentUser;
            if (!user) {
                setMessage("You must be logged in to add data.");
                return;
            }

            await addDoc(collection(db, "categories"), {
                userId: user.uid,
                category: category,
                createdAt: Timestamp.now(),
            });

            // Clear fields and show success toast
            setCategory("");

            toast({
                position: "top",
                title: "Record Added Successfully!",
                status: "success",
                duration: 4000,
                isClosable: true,
            });

            navigate("/addspend");
        } catch (error: any) {
            toast({
                position: "top",
                title: "Error saving data",
                description: error.message,
                status: "error",
                duration: 4000,
                isClosable: true,
            });

            navigate("/addspend");
        }
    }
    return (
        <Box maxW="md" mx="auto" mt={8} p={5} boxShadow="md" borderRadius="md">
            <Heading size="md" mb={4}>Add Expense Record</Heading>
                {message && <Alert status='warning'>
                            <AlertIcon />
                            <AlertTitle>{message}</AlertTitle>
                            </Alert>}
            <VStack spacing={4}>
                <Input
                    placeholder="Category"
                    value={category}
                    onChange={(e) => setCategory(e.target.value)}
                />
                <Button colorScheme="blue" onClick={handleCategorySubmit} width="full">
                    Submit
                </Button>
            </VStack>
        </Box>
    )
}

export default Categories
