import React, { useState } from "react";
import { Tabs, TabList, Tab, TabPanels, TabPanel } from "@chakra-ui/react";
import { ExpensesSummary } from "./ExpensesSummary";
import CategorySummary from "./CategorySummary";

const Expenses:React.FC = () => {

    const tabNames = ['Expenses Records', 'Expenses Categories'];
    const [activeTab, setActiveTab] = useState<string>(tabNames[0]);

    const handleTabChange = (index: number) => {
      setActiveTab(tabNames[index]);
      console.log('Selected Tab:', tabNames[index]); // This is where you get the tab name
    };
  
    return (
      <Tabs colorScheme="blue" onChange={handleTabChange}>
        <TabList>
          {tabNames.map((name, index) => (
            <Tab key={index}>{name}</Tab>
          ))}
        </TabList>

        <TabPanels>
          <TabPanel>
            <ExpensesSummary />
          </TabPanel>
          <TabPanel>
            <CategorySummary />
          </TabPanel>
        </TabPanels>
    </Tabs>
      
    );
};

export default Expenses;