import { collection, getDocs, query, where } from "firebase/firestore";
import { auth, db } from "../auth";
import { Expense } from "../types/expenses";

export const fetchExpenses = async () => {
  const user = auth.currentUser;
  if (!user) return;
  const expensesRef = collection(db, 'expenses');
  const q = query(expensesRef, where('userId', '==', user.uid));
  const snapshot = await getDocs(q);
  const data: Expense[] = snapshot.docs.map(doc => ({
    id: doc.id,
    ...doc.data()
  })) as Expense[];
  return data
};

export const getWeeksInMonth = (year: number, month: number): string[] => {
  const weeks: string[] = ['All'];
  const firstDay = new Date(year, month, 1);
  const lastDay = new Date(year, month, 0);
  let currentWeek = 1;

  for (let day = firstDay.getDate(); day <= lastDay.getDate(); day++) {
    const date = new Date(year, month, day);
    if (day === 1 || date.getDay() === 0) {
      if (!weeks.includes(`Week ${currentWeek}`)) weeks.push(`Week ${currentWeek}`);
    }
    if (date.getDay() === 6) {
      currentWeek++;
    }
  }

  if (!weeks.includes(`Week ${currentWeek}`)) weeks.push(`Week ${currentWeek}`);
  return weeks;
};

export const getWeekRange = (date: Date): number => {
  const firstOfMonth = new Date(date.getFullYear(), date.getMonth(), 1);
  const dayOfMonth = date.getDate();
  const weekNumber = Math.ceil((dayOfMonth + firstOfMonth.getDay()) / 7);
  return weekNumber;
};

export const getWeekDates = (year: number, month: number, weekNumber: number): Date[] => {
  const dates: Date[] = [];
  const firstDay = new Date(year, month, 1);
  const firstDayOfWeek = firstDay.getDay(); // 0 (Sun) - 6 (Sat)
  let start = 1 - firstDayOfWeek + (weekNumber - 1) * 7;

  for (let i = 0; i < 7; i++) {
    const day = new Date(year, month, start + i);
    if (day.getMonth() === month) {
      dates.push(day);
    }
  }

  return dates;
};

export const getExpensesCategoryData = (expenses: Expense[], year:number, month: number, week:string) =>{
  const filtered = expenses.filter((expense) => {
    const date = expense.date.toDate(); // Convert Firestore Timestamp to JS Date
    const expenseYear = date.getFullYear();
    const expenseMonth = date.getMonth();
    const expenseWeek = Math.ceil(date.getDate() / 7);

    const matchYear = expenseYear === year;
    const matchMonth = expenseMonth === month;
    const matchWeek = week === 'All' || week === `Week ${expenseWeek}`;

    return matchYear && matchMonth && matchWeek;
  });

  const grouped: Record<string, number> = {};
  filtered.forEach((expense) => {
    const category = expense.category || 'Uncategorized';
    grouped[category] = (grouped[category] || 0) + expense.amount;
  });

  return grouped
}