import React, { useState } from "react";
import {
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
} from "firebase/auth";
import { Button, Input, Heading, VStack, Text, Flex, Alert, AlertIcon, AlertTitle, AlertDescription, useToast } from "@chakra-ui/react";
import { useNavigate } from "react-router-dom";
import { auth } from "../Firebase";

export const Login: React.FC = () => {
  const [email, setEmail] = useState<string>("");
  const [password, setPassword] = useState<string>("");
  const [error, setError] = useState<string>("");
  const navigate = useNavigate();
  const toast = useToast()

  const handleAuth = async (isLogin: boolean) => {
    try {
      if (isLogin) {
        await signInWithEmailAndPassword(auth, email, password);
      } else {
        await createUserWithEmailAndPassword(auth, email, password);
      }
      toast({
        position: 'top',
        title: 'Login Successfully.',
        status: 'success',
        duration: 9000,
        isClosable: true,
      })
      navigate("/");
    } catch (err: any) {
      setError(err.message);
    }
  };

  return (
    <Flex minH={`${window.innerHeight-50}px`} justify="center" align="center" bg="gray.50">
      <Flex
        direction="column"
        justifyContent="center"
        alignItems="center"
        textAlign="center"
        p={10}
        boxShadow="md"
        borderRadius="md"
        bg="white"
      >
        <Heading mb={5}>Login</Heading>
        {error && <Alert status='error'>
                    <AlertIcon />
                    <AlertTitle>Unauthorized User</AlertTitle>
                    <AlertDescription>Email or Password Incorrect</AlertDescription>
                  </Alert>
        }
        <VStack spacing={4}>
          <Input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            focusBorderColor="blue.500"
          />
          <Input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            focusBorderColor="blue.500"
          />
          <Button colorScheme="green" onClick={() => handleAuth(true)} width="full">
            Login
          </Button>
          <Text>
            Already have an account?{" "}
            <Button variant="link" onClick={() => navigate("/signup")}>
              Register
            </Button>
          </Text>
        </VStack>
      </Flex>
    </Flex>

  );
};

export default Login;
